diff --git a/src/ui/render.ts b/src/ui/render.ts
index aaa1111..bbb2222 100644
--- a/src/ui/render.ts
+++ b/src/ui/render.ts
@@ -30,6 +30,13 @@ export function renderItem(todo: Todo): HTMLElement {
   const title = el('span', { class: 'title', text: todo.title });
   row.append(title);
+  const badge = dueBadge(todo.due);
+  if (badge) row.append(badge);
   return row;
 }
+
+function dueBadge(due: string | undefined): HTMLElement | null {
+  if (!due) return null;
+  const label = due === todayIso() ? 'today' : due < todayIso() ? 'overdue' : null;
+  return label ? el('span', { class: 'badge badge-' + label, text: label }) : null;
+}
